from flask import Flask, request, jsonify
import hashlib

app = Flask(__name__)

# Dictionary to store the sharing links and their corresponding URLs
sharing_links = {}

@app.route('/share', methods=['POST'])
def share_url():
    url = request.json['url']
    link = hashlib.sha256(str(url).encode('utf-8')).hexdigest()
    sharing_links[link] = url
    return jsonify({'link': f'http://localhost:5000/share/{link}'}), 200

@app.route('/share/<link>', methods=['GET'])
def share_link(link):
    if link in sharing_links:
        url = sharing_links[link]
        return jsonify({'url': url}), 200
    else:
        return jsonify({'error': 'Invalid link'}), 404

if __name__ == '__main__':
    app.run(debug=True)
```

