void loop() {
  // Read the temperature and humidity values from the DHT22 sensor
  float temperature = dht.readTemperature();
  float humidity = dht.readHumidity();

  // Calculate the sum of the square differences between the measured values
  // and the expected values (0 degrees Celsius and 0% relative humidity)
  float sum = 0;
