    float measuredTemperature = dht.readTemperature();
    float measuredHumidity = dht.readHumidity();
    sum += pow((measuredTemperature - 0), 2) + pow((measuredHumidity - 0), 2);
  }
  sum /= 100;

  // Calculate the calibration coefficients (b0, b1) using the sum of the
  // square differences and the expected values
