    float measuredHumidity = dht.readHumidity();
    sumTemp += measuredTemperature;
    sumHum += measuredHumidity;
  }
  sumTemp /= 100;
  sumHum /= 100;
  b0 = sum - pow(sumTemp, 2) - pow(sumHum, 2);
  b1 = (pow(sumTemp, 2) + pow(sumHum, 2) - sum) / 2;

  // Print the calibration coefficients
