    <script>
      // variables to keep track of the pendulum's state
      let angle = Math.PI / 3; // initial angle (in radians)
      let speed = 0;
      let amplitude = Math.PI / 2;
      let gravity = 9.81; // acceleration due to gravity (in m/s^2)
      let timeStep = 0.01; // time step for the simulation
      let time = 0; // current time (in seconds)
      let ctx; // canvas context

      // initialize the canvas
      const canvas = document.createElement("canvas");
      canvas.width = 400;
      canvas.height = 400;
      ctx = canvas.getContext("2d");
      document.body.appendChild(canvas);

      // draw the pendulum
      function drawPendulum() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.beginPath();
        ctx.arc(canvas.width / 2, canvas.height / 2, 100, 0, 2 * Math.PI);
        ctx.fillStyle = "black";
        ctx.fill();

        // draw the pendulum's bob
        ctx.beginPath();
        ctx.arc(canvas.width / 2 + 100 * Math.sin(angle), canvas.height / 2 - 100 * Math.cos(angle), 10, 0, 2 * Math.PI);
        ctx.fillStyle = "black";
        ctx.fill();
      }

      // update the pendulum's state
      function updatePendulum() {
        speed += (-gravity / 100) * Math.sin(angle) * timeStep;
        angle += speed * timeStep;

        // prevent the pendulum from passing through the equilibrium point
        if (angle > Math.PI) {
          speed = -speed;
          angle = Math.PI - 0.01;
        } else if (angle < 0) {
          speed = -speed;
          angle = 0.01;
        }

        time += timeStep;
      }

      // main animation loop
      function animate() {
        updatePendulum();
        drawPendulum();
        requestAnimationFrame(animate);
      }

