	sess, err := session.NewSession(&aws.Config{Region: aws.String("your-region")}, nil)
	if err != nil {
		return nil, err
	}

	ec2Svc := ec2.New(sess)

	// Get all EBS snapshots with the "backup_type" tag
	input := &ec2.DescribeSnapshotsInput{
		Filters: []*ec2.Filter{
			{
				Name:   aws.String("tag:backup_type"),
				Values: []*string{"monthly", "daily", "weekly", "yearly"},
			},
		},
	}
	resp, err := ec2Svc.DescribeSnapshots(input)
	if err != nil {
		return nil, err
	}

	// Create a map to store the snapshots by type
	snapshots := make(map[string][]*ec2.Snapshot)

	for _, snapshot := range resp.Snapshots {
		tag, ok := findTag(snapshot.Tags, "backup_type")
		if !ok {
			return nil, fmt.Errorf("snapshot %s is missing 'backup_type' tag", *snapshot.SnapshotId)
		}
		snapshots[*tag] = append(snapshots[*tag], snapshot)
	}

