					if err != nil {
						return nil, err
					}
				}
			}
		case "daily":
			// Keep the last 10 daily snapshots
			isEmpty := true
			var deleted []*string
			for _, snapshot := range snapshotList {
				if isEmpty {
					isEmpty = false
				} else {
					// Delete the oldest snapshots
					deleted = append(deleted, aws.String(*snapshot.SnapshotId))
				}
			}
			for _, id := range deleted {
				err = ec2Svc.DeleteSnapshot(&ec2.DeleteSnapshotInput{SnapshotId: id})
				if err != nil {
					return nil, err
				}
			}
		case "weekly":
			// Keep the last 4 weekly snapshots
